use plasmid_map::{digest,reconstruct,Digest,Input,Junction,Site,SiteDomain};
fn report(ok:bool,msg:&str)->bool{println!("{}: {}",if ok{"PASS"}else{"FAILED"},msg);ok}
fn main(){let mut ok=true;let placed=vec![Site{id:"u".into(),enzyme:"E".into(),position:3,forward:true},Site{id:"v".into(),enzyme:"E".into(),position:15,forward:false}];ok&=report(digest(20,&placed,&["E".into()])==vec![8,12],"clockwise digest includes circular wrap");let input=Input{length:20,domains:vec![SiteDomain{id:"u".into(),enzyme:"E".into(),options:vec![(3,true),(4,false)]},SiteDomain{id:"v".into(),enzyme:"E".into(),options:vec![(15,false),(16,true)]},SiteDomain{id:"w".into(),enzyme:"F".into(),options:vec![(8,true),(9,false)]}],digests:vec![Digest{enzymes:vec!["E".into()],fragments:vec![8,12],tolerance:0},Digest{enzymes:vec!["E".into(),"F".into()],fragments:vec![5,7,8],tolerance:0}],junctions:vec![Junction{a:"u".into(),b:"w".into(),same_orientation:true}]};let map=reconstruct(&input);ok&=report(map.is_some(),"joint digest and junction evidence yields a map");if let Some(m)=map{ok&=report(m.iter().map(|s|s.position).min()==Some(0),"rotation normalization selects zero origin");let u=m.iter().find(|s|s.id=="u");let w=m.iter().find(|s|s.id=="w");ok&=report(matches!((u,w),(Some(a),Some(b)) if a.forward==b.forward),"oriented junction parity is preserved");}std::process::exit(if ok{0}else{1});}
